{
  "task_summary": "Predict whether an NHANES participant has high total cholesterol using survey-era health history and demographic features, emphasizing signals likely to remain predictive across domain shifts.",
  "ranking": [
    {
      "rank": 1,
      "feature_id": 10,
      "rationale": "Age is a strong, biologically stable determinant of cholesterol risk and should generalize well across NHANES domains."
    },
    {
      "rank": 2,
      "feature_id": 0,
      "rationale": "Hypertension is tightly linked to cardiometabolic risk and should remain semantically predictive across populations."
    },
    {
      "rank": 3,
      "feature_id": 2,
      "rationale": "Diabetes status is a robust marker of metabolic dysfunction associated with abnormal lipid profiles."
    },
    {
      "rank": 4,
      "feature_id": 1,
      "rationale": "Prediabetes captures earlier metabolic impairment that is plausibly related to elevated cholesterol."
    },
    {
      "rank": 5,
      "feature_id": 11,
      "rationale": "Sex has a real physiological relationship with lipid levels, though weaker and more shift-sensitive than age or disease history."
    },
    {
      "rank": 6,
      "feature_id": 4,
      "rationale": "Kidney disease can affect lipid metabolism and overall cardiometabolic health, giving moderate stable predictive value."
    },
    {
      "rank": 7,
      "feature_id": 3,
      "rationale": "Recent dialysis indicates severe kidney disease, which is relevant to metabolic health but likely sparse and less broadly informative."
    },
    {
      "rank": 8,
      "feature_id": 6,
      "rationale": "Arthritis may correlate indirectly through age, inflammation, and medication patterns, but is not a primary causal signal."
    },
    {
      "rank": 9,
      "feature_id": 9,
      "rationale": "Education can proxy health behaviors and access to care, but it is also a demographic shortcut that may shift across domains."
    },
    {
      "rank": 10,
      "feature_id": 12,
      "rationale": "Marital status may weakly proxy lifestyle and age structure, but is likely brittle and non-causal for cholesterol."
    },
    {
      "rank": 11,
      "feature_id": 8,
      "rationale": "Country of birth may capture diet or access patterns but is largely a demographic/domain proxy and should be downweighted."
    },
    {
      "rank": 12,
      "feature_id": 5,
      "rationale": "Psoriasis has some inflammatory association with cardiometabolic risk, but the signal is likely weak for this task."
    },
    {
      "rank": 13,
      "feature_id": 7,
      "rationale": "Survey year is primarily a domain identifier and risks exploiting temporal shifts rather than stable individual-level predictors."
    }
  ]
}
